class Shape:
    def area(self):
        # Parent method implementation
        print("Cannot calculate area for generic shape.")
        return 0

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        PI = 3.14
        return PI * (self.radius ** 2)

class Square(Shape):
    def __init__(self, side_length):
        self.side_length = side_length

    def area(self):
        return self.side_length ** 2


def print_area(shape):
    # This function uses polymorphism
    print(f"Calculated Area: {shape.area()}")

# Instances
s1 = Circle(5)
s2 = Square(4)

# Demonstrate
print_area(s1)
print_area(s2)
